import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void layernorm_kernel(
    const T* __restrict__ X,
    const T* __restrict__ G,
    const T* __restrict__ Bt,
    T* __restrict__ Y,
    int N, int M, float eps)
{
  const int n = blockIdx.x;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;

  // CuTe tensors for this batch's flattened slice
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * M), make_shape(M), make_stride(Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * M), make_shape(M), make_stride(Int<1>{}));
  auto mG = make_tensor(make_gmem_ptr(G), make_shape(M), make_stride(Int<1>{}));
  auto mB = make_tensor(make_gmem_ptr(Bt), make_shape(M), make_stride(Int<1>{}));

  float sum = 0.f, sumsq = 0.f;

  // Pass 1: accumulate sum and sum of squares (grid-stride within block)
  for (int i = tid; i < M; i += nthreads) {
    float v = static_cast<float>(mX(i));
    sum += v;
    sumsq += v * v;
  }

  // Warp-level reduction
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum   += __shfl_down_sync(0xffffffff, sum, offset);
    sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
  }

  __shared__ float warpSum[32];
  __shared__ float warpSumSq[32];
  __shared__ float mean_s;
  __shared__ float invstd_s;

  const int warpId = tid / 32;
  const int lane   = tid % 32;

  if (lane == 0) {
    warpSum[warpId]   = sum;
    warpSumSq[warpId] = sumsq;
  }
  __syncthreads();

  const int numWarps = (nthreads + 31) / 32;
  if (tid == 0) {
    float total_sum = 0.f, total_sumsq = 0.f;
    for (int w = 0; w < numWarps; ++w) {
      total_sum   += warpSum[w];
      total_sumsq += warpSumSq[w];
    }
    float mean = total_sum / (float)M;
    float var  = total_sumsq / (float)M - mean * mean;
    if (var < 0.f) var = 0.f;
    float invstd = rsqrtf(var + eps);
    mean_s   = mean;
    invstd_s = invstd;
  }
  __syncthreads();

  const float mean   = mean_s;
  const float invstd = invstd_s;

  // Pass 2: normalize and apply affine transform
  for (int i = tid; i < M; i += nthreads) {
    float v = static_cast<float>(mX(i));
    float g = static_cast<float>(mG(i));
    float b = static_cast<float>(mB(i));
    float y = (v - mean) * invstd * g + b;
    mY(i) = static_cast<T>(y);
  }
}

torch::Tensor cute_layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  int64_t M = w_c.numel();
  TORCH_CHECK(M > 0, "normalized_shape must have non-zero numel");
  TORCH_CHECK(x_c.numel() % M == 0, "x numel must be divisible by normalized_shape numel");
  int64_t N = x_c.numel() / M;

  auto y = torch::empty_like(x_c);

  int threads = 1024;
  dim3 grid((unsigned)N);
  dim3 block((unsigned)threads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  layernorm_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)N, (int)M, (float)eps);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUDA kernel using CuTe tensors
    for indexing. Each CUDA block handles one "outer" batch element and
    performs a block-wide two-pass reduction (mean/variance) followed by the
    affine normalization, all within a single kernel launch.
    """
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            float(self.eps),
        )

