class ModelNew(nn.Module):
    """
    LayerNorm implemented with a hand-authored PTX kernel executed through
    cutegen.ptx_runtime.PtxModule. Each CUDA block normalizes one "outer"
    slice via a two-pass block-wide reduction (mean/variance) followed by
    the affine transform, matching the CuTe/CUDA reference kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._module = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self._module is None:
            self._module = _get_module()

        assert x.is_cuda, "x must be a CUDA tensor"
        x_c = x.contiguous()
        w_c = self.weight.contiguous().to(device=x_c.device, dtype=torch.float32)
        b_c = self.bias.contiguous().to(device=x_c.device, dtype=torch.float32)
        x_c = x_c.to(torch.float32)

        M = w_c.numel()
        assert M > 0, "normalized_shape must have non-zero numel"
        assert x_c.numel() % M == 0, "x numel must be divisible by normalized_shape numel"
        N = x_c.numel() // M

        y = torch.empty_like(x_c)

        threads = 1024
        grid = (int(N), 1, 1)
        block = (threads, 1, 1)

        stream = torch.cuda.current_stream().cuda_stream

        self._module.launch(
            "layernorm_kernel",
            grid=grid,
            block=block,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_c.data_ptr()),
                u64(y.data_ptr()),
                i32(int(N)),
                i32(int(M)),
                f32(float(self.eps)),
            ],
            stream=stream,
        )

        return y
